namespace HarborValeGreybox.Racing.Editor {
public static class RivalsVerification {
 static readonly List<string> checks=new List<string>();static void Check(bool yes,string text){checks.Add((yes?"PASS ":"FAIL ")+text);if(!yes)throw new Exception(text);}static void Reject(Action a,string text){bool rejected=false;try{a();}catch{rejected=true;}Check(rejected,text);}
 static TrialSession Completed(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 static DuelRaceSession Win(DuelContract d,TrialDefinition route){var s=new DuelRaceSession(d,route);s.Tick(4,Vector3.zero,Vector3.zero,Vector3.zero,Vector3.zero);foreach(var g in route.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward,Vector3.zero,Vector3.zero);return s;}
 public static void Prepare(){Directory.CreateDirectory("Assets/HarborValeGreybox/Rivals/Resources");EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HarborValeGreybox/Expansion/Prefabs/AsterFinch.prefab");var instance=(GameObject)PrefabUtility.InstantiatePrefab(source);PrefabUtility.SaveAsPrefabAsset(instance,"Assets/HarborValeGreybox/Rivals/Resources/RivalsFinch.prefab");UnityEngine.Object.DestroyImmediate(instance);AssetDatabase.SaveAssets();}
 public static void Run(){Directory.CreateDirectory("Verification/Rivals");try{Prepare();var route=JsonUtility.FromJson<TrialDefinition>(Resources.Load<TextAsset>("FirstDocksideTrial").text);var data=RivalsData.Load();Check(data.routes.Length==36&&data.routes.All(r=>r.points.Length>100),"36 connected road loops imported without scene regeneration");foreach(var o in data.opponents)Check(WorkshopCatalog.Load("car_finch").Resolve(o.build).PeakKw()>0,"Real authored rival build resolves: "+o.id);
 string root=Path.GetFullPath("Verification/Rivals/profiles/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string old=Path.GetFullPath("Verification/Rivals/fixtures/released-v6.json"),oldBytes=File.ReadAllText(old),file=root+"/v7.json";var prior=JsonUtility.FromJson<RaceProgress>(oldBytes);var store=new RaceProgressStore(file,route,fitmentLegacyFile:old);Check(store.Profile.version==7&&store.Profile.profileId==prior.profileId&&store.Profile.availableCredits==prior.availableCredits&&JsonUtility.ToJson(store.Profile.workshop)==JsonUtility.ToJson(prior.workshop),"Released v6 imports once preserving money, identity and all installed parts");Check(File.ReadAllText(old)==oldBytes&&JsonUtility.ToJson(store.Profile.spending)==JsonUtility.ToJson(prior.spending),"Old file and historical receipt values remain unchanged");Check(store.Profile.fleet.cars.Count==1&&store.Profile.fleet.selectedId==prior.prototypeCarId,"Existing prototype becomes retained owned identity without fake purchase history");
 var fresh=new RaceProgressStore(root+"/fresh-v7.json",route);string freshIdentity=fresh.Profile.profileId;fresh.BeginDuel(Guid.NewGuid().ToString("N"),"rookie","cash");Check(fresh.Profile.profileId==freshIdentity&&File.Exists(root+"/fresh-v7.json"),"Fresh zero-credit profile identity materializes before first cash race");fresh.ForfeitDuel();int cash=store.Profile.availableCredits;var contract=store.BeginDuel(Guid.NewGuid().ToString("N"),"club","cash");Check(store.Profile.fleet.pending.id==contract.id&&store.Profile.availableCredits==cash,"Cash race terms persist before countdown without entry charge");Reject(()=>store.PurchaseWorkshop(Guid.NewGuid().ToString("N"),"drive_awd",5200,out _),"Committed race locks vehicle modifications");var session=Win(contract,route);Check(session.Resolved&&session.Result=="win"&&session.Player.ValidFinish&&!session.Rival.ValidFinish,"Race winner requires player's ordered directional gate completion");store.SettleDuel(session);store.SettleDuel(session);Check(store.Profile.availableCredits==cash+contract.winCredits&&!store.Profile.fleet.HasPending,"Cash result payout is atomic and idempotent");
 var pink=store.BeginDuel(Guid.NewGuid().ToString("N"),"tuned","pinks");var original=FleetLedger.Clone(store.ActiveWorkshop);store.SettleDuel(Win(pink,route));Check(FleetLedger.Find(store.Profile.fleet,pink.opponentId).owner=="player"&&JsonUtility.ToJson(FleetLedger.Find(store.Profile.fleet,pink.opponentId).build)==JsonUtility.ToJson(pink.opponentBuild),"Pink win transfers the actual opponent identity and exact build");store.SelectVehicle(Guid.NewGuid().ToString("N"),pink.opponentId);Check(store.ActiveWorkshop.induction=="small"&&store.ActiveWorkshop.naStage==1,"Won car can be selected with its turbo and tune");int cost=WorkshopCatalog.Load("car_finch").Price(store.ActiveWorkshop,WorkshopCatalog.Load("car_finch").Find("tire_drift"));store.PurchaseWorkshop(Guid.NewGuid().ToString("N"),"tire_drift",cost,out _);Check(store.ActiveWorkshop.tireCompound=="drift"&&JsonUtility.ToJson(store.Profile.workshop)==JsonUtility.ToJson(original),"Won-car upgrade belongs to its identity, retaining original car's build");
 store.BeginDuel(Guid.NewGuid().ToString("N"),"rookie","pinks");store.ForfeitDuel();Check(FleetLedger.Find(store.Profile.fleet,pink.opponentId).owner=="rival"&&store.Profile.fleet.selectedId==prior.prototypeCarId,"Pink loss removes staked car and selects remaining owned car");store.BeginDuel(Guid.NewGuid().ToString("N"),"rookie","pinks");var interrupted=new RaceProgressStore(file,route);interrupted.ForfeitDuel();Check(interrupted.Profile.fleet.selectedId==FleetLedger.Loaner&&interrupted.Profile.fleet.cars.All(c=>c.owner!="player"),"Interrupted last-car stake forfeits once and provides free loaner");Reject(()=>interrupted.BeginDuel(Guid.NewGuid().ToString("N"),"rookie","pinks"),"Loaner cannot be staked");Reject(()=>interrupted.PurchaseWorkshop(Guid.NewGuid().ToString("N"),"na_1",1100,out _),"Loaner cannot consume paid upgrade funds");var loan=interrupted.BeginDuel(Guid.NewGuid().ToString("N"),"rookie","cash");interrupted.SettleDuel(Win(loan,route));Check(interrupted.Profile.fleet.selectedId==FleetLedger.Loaner,"Loaner cash win does not reverse a title loss");int before=interrupted.Profile.availableCredits;string purchase=Guid.NewGuid().ToString("N");interrupted.BuyReplacement(purchase);interrupted.BuyReplacement(purchase);Check(interrupted.Profile.availableCredits==before-data.replacementPrice&&interrupted.Profile.fleet.selectedId.EndsWith(purchase),"Replacement purchase debits once and creates new vehicle identity");Check(FleetLedger.Find(interrupted.Profile.fleet,prior.prototypeCarId).owner=="rival","Lost original remains lost after recovery purchase");var loaded=new RaceProgressStore(file,route);Check(JsonUtility.ToJson(loaded.Profile.fleet)==JsonUtility.ToJson(interrupted.Profile.fleet),"Complete ownership/build/title ledger replays after reload");
 string snapshot=File.ReadAllText(file);var failed=new RaceProgressStore(file,route,()=>{throw new IOException("Injected atomic failure");});Reject(()=>failed.BuyReplacement(Guid.NewGuid().ToString("N")),"Failed fleet commit reports failure");Check(File.ReadAllText(file)==snapshot,"Failed commit leaves cash, car and ownership history unchanged");var fake=JsonUtility.FromJson<RaceProgress>(snapshot);fake.fleet.cars[0].owner="player";string bad=root+"/tampered.json";File.WriteAllText(bad,JsonUtility.ToJson(fake));Reject(()=>new RaceProgressStore(bad,route),"Forged cached ownership cannot override receipt history");fake=JsonUtility.FromJson<RaceProgress>(snapshot);fake.version=8;File.WriteAllText(bad,JsonUtility.ToJson(fake));File.WriteAllText(bad+".bak",snapshot);Reject(()=>new RaceProgressStore(bad,route),"Unknown schema8 is preserved instead of overwritten from backup");Check(File.ReadAllText(old)==oldBytes,"New fleet transactions never edit original v6 source");

 var tie=loaded.BeginDuel(Guid.NewGuid().ToString("N"),"rookie","pinks");Reject(()=>loaded.BeginDuel(tie.id,"rookie","cash"),"Race request retry cannot change stakes mode");var draw=new DuelRaceSession(tie,route);draw.Tick(4,Vector3.zero,Vector3.zero,Vector3.zero,Vector3.zero);foreach(var g in route.checkpoints)draw.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward,g.Position-g.Forward,g.Position+g.Forward);Check(draw.Resolved&&draw.Result=="draw","Same-step photo finish resolves as draw rather than frame-order loss");loaded.SettleDuel(draw);Check(FleetLedger.Find(loaded.Profile.fleet,tie.playerId).owner=="player"&&FleetLedger.Find(loaded.Profile.fleet,tie.opponentId).owner=="rival","Draw keeps both actual title stakes with their original owners");Reject(()=>loaded.BeginDuel(tie.id,"rookie","pinks"),"Completed request cannot create another race contract");var losing=loaded.BeginDuel(Guid.NewGuid().ToString("N"),"club","cash");var second=new DuelRaceSession(losing,route);second.Tick(4,Vector3.zero,Vector3.zero,Vector3.zero,Vector3.zero);foreach(var g in route.checkpoints)second.Tick(.02f,Vector3.zero,Vector3.zero,g.Position-g.Forward,g.Position+g.Forward);foreach(var g in route.checkpoints)second.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward,Vector3.zero,Vector3.zero);int lostCash=loaded.Profile.availableCredits;loaded.SettleDuel(second);Check(second.Result=="finish"&&loaded.Profile.availableCredits==lostCash+losing.finishCredits,"Valid second-place finish grants only frozen completion profit");
 PhysicsRules(data);File.WriteAllLines("Verification/Rivals/rules.txt",checks);
 }catch(Exception e){checks.Add("FAIL "+e);File.WriteAllLines("Verification/Rivals/rules.txt",checks);throw;}}
 static void PhysicsRules(RivalsData data){EditorSceneManager.OpenScene("Assets/HarborValeGreybox/Driving/Scenes/Finch_HandlingTest.unity");foreach(var s in UnityEngine.Object.FindObjectsByType<StarterCarSpecification>())UnityEngine.Object.DestroyImmediate(s.gameObject);var oldMode=Physics.simulationMode;Physics.simulationMode=SimulationMode.Script;var car=TrafficWorld.CreateCar("AI physical fixture",new WorkshopBuild(),0);var pilot=car.gameObject.AddComponent<RoadPilot>();pilot.Car=car;pilot.Path=Enumerable.Range(0,150).Select(i=>new Vector3(10,.08f,i*3)).ToArray();pilot.CruiseKph=35;pilot.Place(0);float peak=0;try{for(int i=0;i<600;i++){pilot.Drive(.02f);car.Tick(.02f);Physics.Simulate(.02f);peak=Mathf.Max(peak,car.SpeedKph);}checks.Add("MEASURE AI speed="+car.SpeedKph+" pos="+car.transform.position+" pedal="+car.commandedPedal+" brake="+car.commandedServiceBrake+" steer="+car.commandedSteer+" ground="+car.GroundedWheels);Check(peak>20&&car.transform.position.z>30,"AI accelerates and follows actual wheel-driven vehicle physics");Check(car.Wheels.Length==4&&car.GetComponentsInChildren<WheelCollider>().Length==4&&!car.Body.isKinematic,"AI has exactly four contacts and a dynamic collision body");var obstacle=GameObject.CreatePrimitive(PrimitiveType.Cube);obstacle.transform.position=car.transform.position+car.transform.forward*8+Vector3.up;obstacle.transform.localScale=new Vector3(3,2,2);Physics.SyncTransforms();pilot.Drive(.02f);Check(car.commandedServiceBrake>0||car.commandedPedal<.2f,"AI obstacle sensing reduces throttle/brakes for blocked lane");UnityEngine.Object.DestroyImmediate(obstacle);}finally{UnityEngine.Object.DestroyImmediate(car.gameObject);Physics.simulationMode=oldMode;}}
 public static void Lap(){Directory.CreateDirectory("Verification/Rivals");EditorSceneManager.OpenScene("Assets/HarborValeGreybox/Scenes/HarborVale_CityMap.unity");foreach(var s in UnityEngine.Object.FindObjectsByType<StarterCarSpecification>())UnityEngine.Object.DestroyImmediate(s.gameObject);var route=JsonUtility.FromJson<TrialDefinition>(Resources.Load<TextAsset>("FirstDocksideTrial").text);var data=RivalsData.Load();var mode=Physics.simulationMode;Physics.simulationMode=SimulationMode.Script;var car=TrafficWorld.CreateCar("Full city rival fixture",data.opponents[1].build,1);var pilot=car.gameObject.AddComponent<RoadPilot>();pilot.Car=car;pilot.Path=route.route.Select(p=>p.Position).ToArray();pilot.IsRival=true;pilot.CruiseKph=63;var first=route.checkpoints[0];car.ResetAt(first.Position-first.Forward*12+Vector3.Cross(Vector3.up,first.Forward)*1.7f+Vector3.up*.35f,Quaternion.LookRotation(first.Forward));var session=new TrialSession(route);var rows=new List<string>();Vector3 previous=car.transform.position;float stalled=0;int lastGate=0;try{for(int i=0;i<30000&&!session.ValidFinish;i++){pilot.Held=session.State==TrialState.Countdown;car.controlsLocked=pilot.Held;pilot.Drive(.02f);car.Tick(.02f);Physics.Simulate(.02f);session.Tick(.02f,previous,car.transform.position);previous=car.transform.position;if(lastGate==session.NextGate)stalled+=.02f;else{lastGate=session.NextGate;stalled=0;}if(session.State==TrialState.Running&&stalled>45){pilot.RecoverAt(session.Recover());previous=car.transform.position;stalled=0;}if(i%2000==0)rows.Add("MEASURE time="+i*.02f+" gate="+session.NextGate+" speed="+car.SpeedKph+" pos="+car.transform.position+" path="+pilot.Index+" recoveries="+pilot.Recoveries);}rows.Add((session.ValidFinish?"PASS ":"FAIL ")+"AI completes full2042m city loop using ordered gates and dynamic physics; gates="+session.NextGate+" time="+session.Elapsed+" recoveries="+pilot.Recoveries);File.WriteAllLines("Verification/Rivals/lap.txt",rows);if(!session.ValidFinish)throw new Exception("AI did not finish city loop");}finally{UnityEngine.Object.DestroyImmediate(car.gameObject);Physics.simulationMode=mode;}}
 public static void Release(){Run();Lap();HarborValeGreybox.Workshop.Editor.AvCameraVerification.Run();HarborValeGreybox.Workshop.Editor.TurboAudioVerification.Run();HarborValeGreybox.Presentation.Editor.CityArtVerification.Release();}
}
